import{_ as e,o as p,c as o,a5 as a}from"./chunks/framework.BPFk9-tb.js";const m=JSON.parse('{"title":"保持耐心做长期成长","description":"","frontmatter":{"date":"2019-05-31T09:46:25","title":"保持耐心做长期成长","categories":["指数增长"],"tags":["耐心"]},"headers":[],"relativePath":"posts/misc/exponential.md","filePath":"posts/misc/exponential.md"}'),s={name:"posts/misc/exponential.md"};function i(n,t,l,_,r,c){return p(),o("div",null,[...t[0]||(t[0]=[a("<p>在前一家公司的时候一次会议上，老板举了个例子，是从现在有多少荷花（具体多少已记不清了），荷花每天长一倍，问多少天长满池塘。这是一个奥数题的翻版：</p><blockquote><p>池塘里的荷花每天长一倍，30天长满一池塘，问多少天覆盖整个池塘的四分之一？</p></blockquote><p>大家都抢着回答。我当时没有什么感觉，自己也不是智力出众型，不能马上答上来，所以把更多的注意力放了在如何做对这道题，而不显得那么傻上，现在想想也觉得好笑。</p><p>而现在回想起来老板是希望我们关注以下几点吧：</p><ol><li><p>关注的是指数增长。但我除了课堂的学习从未将它与生活，工作联系起来。</p></li><li><p>体会时间的重要性。但因为是按天来算的，反而我低估了时间的力量。</p></li><li><p>关注增长率，但因为是成倍增长，让我高估了成长率。</p></li></ol><p>一个例子被举出来时，听的人可能很大程度上不能感同身受，不能体会它的力量。但就像是种下一颗种子一样，在那等待生根发芽，静待花开，突然你会有一天发现，而后感叹。</p><p>从近期的学习来看，我们的成长速度显然不大可能达不到荷花的程度，但保持足够的耐心，特别是接受自己起步时的不好，一定会看到一个指数的增长。</p><p>另外需要记住70这个数字（Why not 42），如果成长率是1%，那么需要70年翻倍。（《清醒的思考艺术》P138，指数增长，计算倍增时间，请用数字70除以增长的百分比。）</p>",8)])])}const f=e(s,[["render",i]]);export{m as __pageData,f as default};
